def paper_row(r):
    year,title,authors,journal,arxiv,doi,summary=r
    authors=html.escape(authors).replace('Hyeongmuk Lim','<strong>Hyeongmuk Lim</strong>')
    doi_link = f'<a href="https://doi.org/{doi}" target="_blank">Journal ↗</a>' if doi else ''
    return f'''<article class="paper-card"><span class="paper-year">{year}</span><div class="paper-header"><h3>{html.escape(title)}</h3></div><div class="paper-authors">{authors}</div><p class="paper-journal">{html.escape(journal)}</p><p class="paper-summary">{html.escape(summary)}</p><div class="paper-actions"><a target="_blank" href="https://arxiv.org/abs/{arxiv}">arXiv ↗</a>{doi_link}<a target="_blank" href="https://arxiv.org/pdf/{arxiv}">PDF ↗</a></div></article>'''

papers='\n'.join(map(paper_row,entries))
